# HELPER FUNCTIONS:

# Round table numbers to 2 decimals
round_table_nums_2 <- function(lines) {
  obs_idx <- grep("^Observations[[:space:]]*&", lines)
  if (length(obs_idx) == 0) stop("Could not find Observations row.")
  coef_block <- seq_len(obs_idx[1] - 1)
  lines[coef_block] <- sapply(lines[coef_block], function(z) {
    if (grepl("R\\$\\^2\\$|Adjusted R\\$\\^2\\$", z)) return(z)
    stringr::str_replace_all(z, "-?[0-9,]+\\.[0-9]+", function(m) {formatC(as.numeric(gsub(",", "", m)), format = "f", digits = 2, big.mark = ",")})
  })
  lines
}

fix_table_dashes <- function(x) {
  x <- gsub("2001-2016", "2001--2016", x)
  x <- gsub("2001–2016", "2001--2016", x)
  x <- gsub("2001−2016", "2001--2016", x)
  x <- gsub("2016-2021", "2016--2021", x)
  x <- gsub("2016–2021", "2016--2021", x)
  x <- gsub("2016−2021", "2016--2021", x)
  x <- gsub("0-100", "0--100", x)
  x <- gsub("0–100", "0--100", x)
  x <- gsub("0−100", "0--100", x)
  x <- gsub("0-1", "0--1", x)
  x <- gsub("0–1", "0--1", x)
  x <- gsub("0−1", "0--1", x)
  x <- gsub("\\(1\\)-\\(3\\)", "(1)--(3)", x)
  x <- gsub("\\(2\\)-\\(6\\)", "(2)--(6)", x)
  x <- gsub("\\(7\\)-\\(9\\)", "(7)--(9)", x)
  x}

fmt_latex_num <- function(z, digits = 2) {out <- formatC(abs(z), format = "f", digits = digits, big.mark = ","); ifelse(z < 0, paste0("$-$", out), out)}

