c5_mean <- round(mean(c5$model$claims_2001_2016, na.rm = TRUE) / 1000, 2)
c6_mean <- round(mean(c6$model$claims_2001_2016, na.rm = TRUE) / 1000, 2)

raw_file <- "output/tables/03112026_coastal_models.tex"
new_file <- "output/tables/03112026_coastal_models_all_NEW.tex"
x <- readLines(raw_file)

coastal_panel_rows <- c(
  "Baseline controls & \\checkmark & \\checkmark & \\checkmark & \\checkmark & \\checkmark & \\checkmark \\\\",
  "Full sample & \\checkmark & \\checkmark &  &  & \\checkmark & \\checkmark \\\\",
  "Harvey ZIPs only &  &  & \\checkmark & \\checkmark &  &  \\\\")
mean_row <- paste0("Mean dep. var. (\\$000s) & ", c1_mean, " & ", c2_mean, " & ", c3_mean, " & ", c4_mean, " & ", c5_mean, " & ", c6_mean, " \\\\")

obs_idx <- grep("^Observations[[:space:]]*&", x)
if (length(obs_idx) == 0) stop("Could not find Observations row in coastal table.")

hline_idx <- grep("^\\\\hline", x)
panel_hline_idx <- max(hline_idx[hline_idx < obs_idx[1]])

x_new <- c(x[1:panel_hline_idx], coastal_panel_rows, mean_row, x[obs_idx[1]:length(x)])
x_new <- fix_table_dashes(x_new)
writeLines(x_new, new_file)


